return [ 'en' => [ 'about' => [ [ 'type' => 'paragraph', 'text' => 'Types & Fields QuickNav brings the administration of your content types and custom fields into the WordPress toolbar. Reach field groups, post type definitions, taxonomies and available provider settings from one familiar place.' ], [ 'type' => 'paragraph', 'text' => 'It is part of the deckerweb QuickNav series: small, focused tools that make everyday WordPress administration easier. Each QuickNav plugin shortens the path to existing tools while respecting their own interfaces and permissions.' ], [ 'type' => 'paragraph', 'text' => 'Whether you maintain your own projects or move between client websites, Types & Fields QuickNav adapts to the providers that are actually available. Configure the navigation for each website and decide who sees it.' ] ], 'documentation' => [ [ 'type' => 'heading', 'text' => 'First steps' ], [ 'type' => 'paragraph', 'text' => 'Download the installable plugin ZIP from Releases: https://github.com/deckerweb/types-fields-quicknav/releases. In WordPress, open Plugins → Add Plugin → Upload Plugin, upload the ZIP and activate it. Then open Settings → Types & Fields QuickNav. Select the provider menus for this website. Add-on links, frontend navigation and content lists are optional and initially off.' ], [ 'type' => 'heading', 'text' => 'Which providers are supported?' ], [ 'type' => 'paragraph', 'text' => 'ACF Free/Pro, Meta Box with available extensions, JetEngine, ACPT Free/Pro and Pods. Toolset and Secure Custom Fields are also supported. Several compatible providers can appear together.' ], [ 'type' => 'heading', 'text' => 'Does QuickNav replace or modify my providers?' ], [ 'type' => 'paragraph', 'text' => 'It opens existing administration pages. Field definitions, content, roles and provider configuration remain under the provider’s control.' ], [ 'type' => 'heading', 'text' => 'Why is a toolbar entry missing?' ], [ 'type' => 'paragraph', 'text' => 'The required provider or module may be inactive, its admin menu unavailable, or the current user may lack permission. Check the provider, destination and add-on switches, as well as role and user exclusions for this website.' ], [ 'type' => 'heading', 'text' => 'How do I enable ACF add-ons?' ], [ 'type' => 'paragraph', 'text' => 'Open Settings → Types & Fields QuickNav → Add-ons → Extensions for ACF. Enable the desired add-on. ACF Extended requires ACF Pro. An active add-on and its QuickNav visibility are independent states.' ], [ 'type' => 'heading', 'text' => 'Can I hide the menu from client roles or individual users?' ], [ 'type' => 'paragraph', 'text' => 'Yes. Under General, select excluded roles or enter exact WordPress usernames. Any matching role or user exclusion hides the complete QuickNav toolbar entry in the administration area and frontend. Authorized administrators retain access through the WordPress Settings menu.' ], [ 'type' => 'heading', 'text' => 'What is available in the frontend and on multisite?' ], [ 'type' => 'paragraph', 'text' => 'Frontend navigation is off by default. When enabled, it includes verified definition post types and optional content lists; menu-based provider screens remain administration-only. Each multisite website keeps its own settings and exclusions.' ], [ 'type' => 'heading', 'text' => 'What happens on deactivation or uninstall?' ], [ 'type' => 'paragraph', 'text' => 'Settings are retained by default. Each website may opt in to deleting its own QuickNav settings on uninstall. Provider content and data are never removed. Shared Library cleanup follows its own settings and last-host rules.' ] ] ], 'de' => [ 'about' => [ [ 'type' => 'paragraph', 'text' => 'Types & Fields QuickNav bringt die Verwaltung deiner Inhaltstypen und individuellen Felder in die WordPress-Toolbar. Feldgruppen, Inhaltstyp-Definitionen, Taxonomien und verfügbare Provider-Einstellungen sind damit an einem vertrauten Ort erreichbar.' ], [ 'type' => 'paragraph', 'text' => 'Das Plugin gehört zur QuickNav-Serie von deckerweb: kleine, gezielte Werkzeuge, die den WordPress-Alltag erleichtern. Jedes QuickNav-Plugin verkürzt die Wege zu vorhandenen Funktionen und berücksichtigt dabei deren eigene Oberflächen und Berechtigungen.' ], [ 'type' => 'paragraph', 'text' => 'Ob eigene Projekte oder wechselnde Kunden-Websites: Types & Fields QuickNav passt sich an die tatsächlich verfügbaren Provider an. Die Navigation lässt sich für jede Website konfigurieren – einschließlich der Frage, wer sie sehen darf.' ] ], 'documentation' => [ [ 'type' => 'heading', 'text' => 'Erste Schritte' ], [ 'type' => 'paragraph', 'text' => 'Das installierbare Plugin-ZIP unter Releases: https://github.com/deckerweb/types-fields-quicknav/releases herunterladen. In WordPress unter Plugins → Plugin hinzufügen → Plugin hochladen installieren und aktivieren. Anschließend Einstellungen → Types & Fields QuickNav öffnen und die Provider-Menüs für diese Website auswählen. Add-on-Links, Frontend-Navigation und Inhaltslisten sind optional und zunächst ausgeschaltet.' ], [ 'type' => 'heading', 'text' => 'Welche Provider werden unterstützt?' ], [ 'type' => 'paragraph', 'text' => 'ACF Free/Pro, Meta Box mit verfügbaren Erweiterungen, JetEngine, ACPT Free/Pro und Pods. Toolset und Secure Custom Fields werden ebenfalls unterstützt. Mehrere kompatible Provider können gleichzeitig erscheinen.' ], [ 'type' => 'heading', 'text' => 'Ersetzt oder verändert QuickNav meine Provider?' ], [ 'type' => 'paragraph', 'text' => 'Das Plugin öffnet vorhandene Verwaltungsseiten. Felddefinitionen, Inhalte, Rollen und Provider-Konfiguration bleiben unter der Kontrolle des jeweiligen Providers.' ], [ 'type' => 'heading', 'text' => 'Warum fehlt ein Toolbar-Eintrag?' ], [ 'type' => 'paragraph', 'text' => 'Der benötigte Provider oder ein Modul ist möglicherweise inaktiv, das Verwaltungsmenü fehlt oder der aktuelle Benutzer hat keine ausreichende Berechtigung. Provider-, Menüpunkt- und Add-on-Schalter sowie Rollen- und Benutzersperren dieser Website prüfen.' ], [ 'type' => 'heading', 'text' => 'Wie aktiviere ich die ACF-Add-ons?' ], [ 'type' => 'paragraph', 'text' => 'Unter Einstellungen → Types & Fields QuickNav → Add-ons → Erweiterungen für ACF die gewünschte Erweiterung einschalten. ACF Extended benötigt ACF Pro. Die Aktivität eines Add-ons und seine Anzeige durch QuickNav sind unabhängig voneinander.' ], [ 'type' => 'heading', 'text' => 'Kann ich das Menü für Kundenrollen oder einzelne Benutzer ausblenden?' ], [ 'type' => 'paragraph', 'text' => 'Ja. Unter Allgemein die gesperrten Rollen auswählen oder die genauen WordPress-Benutzernamen eingeben. Jeder passende Rollen- oder Benutzereintrag blendet das gesamte QuickNav-Toolbar-Menü im Verwaltungsbereich und Frontend aus. Berechtigte Administratoren behalten den Zugang über das WordPress-Menü Einstellungen.' ], [ 'type' => 'heading', 'text' => 'Was ist im Frontend und in Multisite verfügbar?' ], [ 'type' => 'paragraph', 'text' => 'Die Frontend-Navigation ist zunächst ausgeschaltet. Nach Aktivierung zeigt sie geprüfte Definitions-Inhaltstypen und optionale Inhaltslisten; menübasierte Provider-Seiten bleiben auf den Verwaltungsbereich beschränkt. Jede Multisite-Website erhält eigene Einstellungen und Sperren.' ], [ 'type' => 'heading', 'text' => 'Was geschieht bei Deaktivierung oder Deinstallation?' ], [ 'type' => 'paragraph', 'text' => 'Einstellungen bleiben standardmäßig erhalten. Jede Website kann ihre eigenen QuickNav-Einstellungen bei der Deinstallation ausdrücklich löschen lassen. Inhalte und Daten der Provider werden nicht entfernt. Gemeinsame Library-Daten folgen den eigenen Einstellungen und Letzt-Host-Regeln.' ] ] ], 'de_formal' => [ 'about' => [ [ 'type' => 'paragraph', 'text' => 'Types & Fields QuickNav bringt die Verwaltung Ihrer Inhaltstypen und individuellen Felder in die WordPress-Toolbar. Feldgruppen, Inhaltstyp-Definitionen, Taxonomien und verfügbare Provider-Einstellungen sind damit an einem vertrauten Ort erreichbar.' ], [ 'type' => 'paragraph', 'text' => 'Das Plugin gehört zur QuickNav-Serie von deckerweb: kleine, gezielte Werkzeuge, die den WordPress-Alltag erleichtern. Jedes QuickNav-Plugin verkürzt die Wege zu vorhandenen Funktionen und berücksichtigt dabei deren eigene Oberflächen und Berechtigungen.' ], [ 'type' => 'paragraph', 'text' => 'Ob eigene Projekte oder wechselnde Kunden-Websites: Types & Fields QuickNav passt sich an die tatsächlich verfügbaren Provider an. Die Navigation lässt sich für jede Website konfigurieren – einschließlich der Frage, wer sie sehen darf.' ] ], 'documentation' => [ [ 'type' => 'heading', 'text' => 'Erste Schritte' ], [ 'type' => 'paragraph', 'text' => 'Das installierbare Plugin-ZIP unter Releases: https://github.com/deckerweb/types-fields-quicknav/releases herunterladen. In WordPress unter Plugins → Plugin hinzufügen → Plugin hochladen installieren und aktivieren. Anschließend Einstellungen → Types & Fields QuickNav öffnen und die Provider-Menüs für diese Website auswählen. Add-on-Links, Frontend-Navigation und Inhaltslisten sind optional und zunächst ausgeschaltet.' ], [ 'type' => 'heading', 'text' => 'Welche Provider werden unterstützt?' ], [ 'type' => 'paragraph', 'text' => 'ACF Free/Pro, Meta Box mit verfügbaren Erweiterungen, JetEngine, ACPT Free/Pro und Pods. Toolset und Secure Custom Fields werden ebenfalls unterstützt. Mehrere kompatible Provider können gleichzeitig erscheinen.' ], [ 'type' => 'heading', 'text' => 'Ersetzt oder verändert QuickNav meine Provider?' ], [ 'type' => 'paragraph', 'text' => 'Das Plugin öffnet vorhandene Verwaltungsseiten. Felddefinitionen, Inhalte, Rollen und Provider-Konfiguration bleiben unter der Kontrolle des jeweiligen Providers.' ], [ 'type' => 'heading', 'text' => 'Warum fehlt ein Toolbar-Eintrag?' ], [ 'type' => 'paragraph', 'text' => 'Der benötigte Provider oder ein Modul ist möglicherweise inaktiv, das Verwaltungsmenü fehlt oder der aktuelle Benutzer hat keine ausreichende Berechtigung. Provider-, Menüpunkt- und Add-on-Schalter sowie Rollen- und Benutzersperren dieser Website prüfen.' ], [ 'type' => 'heading', 'text' => 'Wie aktiviere ich die ACF-Add-ons?' ], [ 'type' => 'paragraph', 'text' => 'Unter Einstellungen → Types & Fields QuickNav → Add-ons → Erweiterungen für ACF die gewünschte Erweiterung einschalten. ACF Extended benötigt ACF Pro. Die Aktivität eines Add-ons und seine Anzeige durch QuickNav sind unabhängig voneinander.' ], [ 'type' => 'heading', 'text' => 'Kann ich das Menü für Kundenrollen oder einzelne Benutzer ausblenden?' ], [ 'type' => 'paragraph', 'text' => 'Ja. Unter Allgemein die gesperrten Rollen auswählen oder die genauen WordPress-Benutzernamen eingeben. Jeder passende Rollen- oder Benutzereintrag blendet das gesamte QuickNav-Toolbar-Menü im Verwaltungsbereich und Frontend aus. Berechtigte Administratoren behalten den Zugang über das WordPress-Menü Einstellungen.' ], [ 'type' => 'heading', 'text' => 'Was ist im Frontend und in Multisite verfügbar?' ], [ 'type' => 'paragraph', 'text' => 'Die Frontend-Navigation ist zunächst ausgeschaltet. Nach Aktivierung zeigt sie geprüfte Definitions-Inhaltstypen und optionale Inhaltslisten; menübasierte Provider-Seiten bleiben auf den Verwaltungsbereich beschränkt. Jede Multisite-Website erhält eigene Einstellungen und Sperren.' ], [ 'type' => 'heading', 'text' => 'Was geschieht bei Deaktivierung oder Deinstallation?' ], [ 'type' => 'paragraph', 'text' => 'Einstellungen bleiben standardmäßig erhalten. Jede Website kann ihre eigenen QuickNav-Einstellungen bei der Deinstallation ausdrücklich löschen lassen. Inhalte und Daten der Provider werden nicht entfernt. Gemeinsame Library-Daten folgen den eigenen Einstellungen und Letzt-Host-Regeln.' ] ] ] ];
